// Spawn Object handles: runtimeObjects index of each node's
// latest clone (-1 = none). Reset with the owning script's
// scene-generation state.
static int flowSpawned[1] = {-1};

// Scene "main": graph of "spawner" (object 3)
class FlowGraphScript_0_3 : public Script {
 public:
  void update(ScriptContext& ctx) override {
    if (ctx.scene != 0) return;
    if (ctx.sceneGeneration != generation) {
      // scene was (re)loaded - back to the initial state
      generation = ctx.sceneGeneration;
      frame = 0;
      started = false;
      flowSpawned[0] = -1;
      delay4 = 0;
    }
    frame++;
    if (delay4 > 0 && --delay4 == 0) {
      if (flowSpawned[0] >= 0 && flowSpawned[0] < ctx.objectCount) {
      if (ctx.despawnObject) ctx.despawnObject(flowSpawned[0]);
      flowSpawned[0] = -1;
      }
    }
    if (frame % everyFrames(5.0F) == 0) {
      flowSpawned[0] = ctx.spawnObject ? ctx.spawnObject(1, ctx.objects[2].data.position[0], ctx.objects[2].data.position[1], ctx.objects[2].data.position[2], 0.0F) : -1;
      delay4 = everyFrames(3.0F);
    }
  }

 private:
  unsigned int generation = 0;
  int frame = 0;
  bool started = false;
  int delay4 = 0;
};

